window.REPORT_PRELOAD_CACHE["RBLX.html"] = {"version":"405aeeda1286fd86cf2964326a505d3a9af7bce009863ff5e3db6879bdca81ef","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Roblox (NYSE: RBLX) 深度研究报告：从青少年游戏沙盒到 10 亿日活沉浸式社交与 AI 驱动 UGC 经济生态</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            rblx: {\n              400: '#FF5A4E',\n              500: '#EE3124',\n              600: '#C81E13',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微光 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(238, 49, 36, 0.24) 0%, rgba(59, 130, 246, 0.06) 100%);\n      border-left: 3px solid #EE3124;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-rblx-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-rblx-500 via-rose-500 to-accent-500 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-rblx-500 to-rblx-600 flex items-center justify-center font-extrabold text-white shadow border border-white/15\">\n        RBLX\n      </div>\n      <div>\n        <div class=\"text-[11px] text-rblx-400 font-semibold tracking-wider uppercase\">NYSE: RBLX · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">Roblox 深度投资研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">RBLX 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 摘要与核心投资要点</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康度与估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策、情景推演与风险配置</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球互动娱乐与 UGC 平台研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (FY25 / FY26E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-rblx-500 to-rblx-600 flex items-center justify-center text-white font-extrabold text-sm shadow-lg shadow-rblx-500/25 border border-white/15\">\n            RBLX\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-rblx-400 bg-rblx-500/15 px-2 py-0.5 rounded border border-rblx-500/30\">NYSE: RBLX</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Roblox 深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          全球头部沉浸式社交平台 · AI 驱动 UGC 经济与数字广告现金流引擎\n        </p>\n      </div>\n\n      <!-- 侧边栏关键财务快照卡片 -->\n      <div class=\"px-5 py-3 bg-navy-950/75 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">2025 全年 Bookings</span>\n          <span class=\"font-mono font-bold text-white\">~$6.78B <span class=\"text-rblx-400\">(+55% YoY)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">2025 GAAP 营收</span>\n          <span class=\"font-mono font-bold text-teal-400\">~$4.89B <span class=\"text-slate-400\">(递延确认)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">2025 自由现金流 FCF</span>\n          <span class=\"font-mono font-bold text-emerald-400\">~$1.36B <span class=\"text-slate-400\">(FCF率 20%+)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">DAU & 净现金储备</span>\n          <span class=\"font-mono font-bold text-rblx-400\">~1.44亿 · 净现金 ~$3.8B</span>\n        </div>\n      </div>\n\n      <!-- 六个核心章节目录导航 -->\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-335px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-rblx-400 mr-2\">00</span>摘要与核心投资要点</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康度与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策、推演与风险配置</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-rblx-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-rblx-500 hover:bg-rblx-600 text-white text-xs font-bold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. 摘要与核心投资要点 (Executive Summary)\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元数据标签栏 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-rblx-500/15 text-rblx-600 dark:text-rblx-400 font-bold border border-rblx-500/30\">评级：增持 / 平台型高弹性成长标的</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">主线：10亿日活愿景 × AI 创作平权 × 现金流拐点</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖基准：FY2025 / FY2026E</span>\n            <span>NYSE: RBLX</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-[#171E31] to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <!-- 背景熔岩红几何点阵 -->\n          <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#EE3124 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-rblx-500/20 border border-rblx-500/40 text-rblx-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-rblx-500 animate-pulse\"></span>\n              <span>CORE THESIS · 从青少年沙盒跃迁为“AI 驱动的沉浸式社交与创作者经济体”</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              Roblox (NYSE: RBLX) 深度研究报告：从青少年游戏沙盒到 10 亿日活沉浸式社交与 AI 驱动 UGC 经济生态\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              Roblox 已经跨越了单一青少年沙盒游戏的边界，进化为全球规模最大的实时 3D 沉浸式社交与用户生成内容（UGC）经济体。2025 全年公司预订额（Bookings）飙升至 <strong class=\"text-white\">~$6.78B (+55% YoY)</strong>，GAAP 营收达 <strong class=\"text-teal-400\">~$4.89B</strong>，自由现金流（FCF）爆发至 <strong class=\"text-emerald-400\">~$1.36B</strong>（FCF 率突破 20%）。\n              随着日活跃用户（DAU）迈向 <strong class=\"text-rblx-400\">~1.44 亿</strong>、13 岁以上及 18+ 成人用户占比持续过半、自研 <strong class=\"text-white\">Cube 3D 基础大模型</strong>大幅降低创作门槛，叠加网页/PC 端直充降费与沉浸式品牌广告起量，Roblox 正迎来运营杠杆全面释放的盈利与现金流双拐点。\n            </p>\n\n            <!-- 核心投资结论高亮条（三栏多空与定位摘要） -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">商业模式与平台定位</div>\n                <div class=\"text-white font-semibold\">零边际内容研发成本的双边网络平台，由虚拟币抽成升级为“社交+广告+电商”生态</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">核心财务与运营拐点</div>\n                <div class=\"text-emerald-400 font-semibold\">Bookings 达 $6.78B，FCF 跃升至 $1.36B，PC/网页直充加速绕开 30% 移动商店税</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">核心多空博弈焦点</div>\n                <div class=\"text-rblx-400 font-semibold\">多头押注成人化与 AI 推动 10 亿 DAU 与 25%+ FCF 率；空头关注合规监管与 GAAP 亏损收敛速度</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>2025 全年预订额 (Bookings)</span>\n              <span class=\"p-1.5 rounded-lg bg-rblx-500/15 text-rblx-600 dark:text-rblx-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$6.78B</span>\n              <span class=\"text-xs font-bold text-rblx-600 dark:text-rblx-400 bg-rblx-500/15 px-2 py-0.5 rounded\">+55% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              爆款内容现象级破圈与全球多端普及驱动，2026E 预订额共识进一步向 $8.2B+ 迈进。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>2025 全年自由现金流 (FCF)</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.36B</span>\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">FCF 率 20.1%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              预收账款商业模式叠加基建与研发费用率收敛，自由现金流实现跨越式爆发。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>全球日活跃用户 (DAU)</span>\n              <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~1.44亿</span>\n              <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">13+岁占比 &gt;60%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              向 10 亿日活长期愿景稳步推进，18+ 成人用户成为增速最快的核心高净值人群。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>开发者生态年度分成 (DevEx)</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;$1.2B</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">头部工作室年入千万美元</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              数百万活跃创作者与专业游戏工作室持续涌入，构建全行业最繁荣的内容供给飞轮。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-rblx-600 dark:text-rblx-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：双轨会计机制、三大变现引擎与渠道降本</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">核心特征：Robux 预售递延确认（~27–28个月摊销周期）</span>\n        </div>\n\n        <!-- 1. 独特的双轨财务机制与成本结构拆解卡片 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center space-x-2.5 mb-3\">\n              <span class=\"px-2.5 py-1 rounded-md bg-rblx-500/15 text-rblx-600 dark:text-rblx-400 text-xs font-bold\">会计核心机制</span>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">Bookings（预订额）vs GAAP Revenue（营收）</h3>\n            </div>\n            <p class=\"text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n              用户使用法币购买虚拟货币 <strong>Robux</strong> 时，现金立即全额流入公司账户并计入当期 <strong>Bookings（预订额）</strong>；但根据美国通用会计准则（GAAP），用于购买耐久型虚拟道具的 Robux 必须在用户的平均付费生命周期（约 <strong>27–28 个月</strong>）内按月分期递延确认为 <strong>GAAP Revenue</strong>。因此，在高速增长期，Bookings 显著高于 GAAP 营收，且预先沉淀出巨额无息预收现金流。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center space-x-2.5 mb-3\">\n              <span class=\"px-2.5 py-1 rounded-md bg-teal-500/15 text-teal-600 dark:text-teal-400 text-xs font-bold\">成本与利润率密码</span>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">COGS 渠道税优化、DevEx 分润与安全基建</h3>\n            </div>\n            <p class=\"text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n              成本端主要由三大块构成：<strong>① 支付渠道抽成（COGS ~22%–24% Bookings）</strong>：iOS/Google Play 传统抽成高达 30%，Roblox 正通过 PC/网页端直充奖励（多送至高 25% Robux）及预付礼品卡大力提升直充比例以压降渠道税；<strong>② 开发者分润（DevEx ~18%–20% Bookings）</strong>；<strong>③ 全球云端基建与信任安全审核</strong>，随规模效应展现显著边际成本递减。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互式 Chart.js 双视图面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：双视图图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2021–2026E 预订额 (Bookings)、GAAP 营收与自由现金流跃升</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">2025 Bookings 达 $6.78B (+55%)，预先现金流沉淀推动 FCF 飙升至 $1.36B</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('financial')\" id=\"btn-chart-fin\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-rblx-600 dark:text-rblx-400 shadow-sm transition\">预订额与现金流演进</button>\n                <button onclick=\"switchBizChart('region')\" id=\"btn-chart-reg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">全球五大区域 DAU vs ABPDAU</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：三大变现引擎深度拆解 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">三大核心商业变现引擎</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-rblx-500/15 text-rblx-600 dark:text-rblx-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">C 端虚拟商品与通行证抽成（核心基本盘）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      玩家消耗 Robux 购买体验内通行证（Game Passes）、角色虚拟形象服饰（Avatar Marketplace）及私人服务器，平台从中抽取约 <strong>30%–70%</strong> 的经济闭环分成。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">沉浸式品牌广告与数字电商（第二增长曲线）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      携手 Google Ad Manager、PubMatic 等程序化广告巨头推出 3D 传送门广告与视频广告牌；联合 Nike、Gucci、Walmart 打通“虚拟试穿 + 实景电商购物”商业闭环，变现海量非付费 DAU。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">开发者订阅与创作者工具生态（Creator Store）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      创作者在 Creator Store 交易 3D 模型、插件、音频及 AI 资产包，叠加企业级品牌定制体验与高级算力订阅，打造 B2D（Business-to-Developer）高毛利软件生态。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">单用户变现结构</span>\n              <span class=\"font-bold text-rblx-600 dark:text-rblx-400\">北美 ABPDAU 领跑全球 · 亚太驱动 DAU 扩张</span>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 行业地位与四重核心护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：UGC 飞轮与 AI 创作平权</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球最大实时 3D 社交网络)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四重核心壁垒卡片网格 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 壁垒 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-rblx-500/15 text-rblx-600 dark:text-rblx-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">UGC 飞轮与零边际内容研发成本</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                传统 3A 游戏大厂单款大作研发周期长达 5 年、投入数亿美元且面临“单品扑街”风险；Roblox 汇聚<strong>数百万活跃创作者</strong>，平台无需承担前置内容研发沉没成本，仅对已验证成功的爆款分配 DevEx 分润，实现千万级体验的指数级涌现。\n              </p>\n            </div>\n\n            <!-- 壁垒 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨端无缝引擎与全球低延迟云基建</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                开发者只需使用 Roblox Studio 编写一次代码，即可一键同步部署至 iOS、Android、Windows、macOS、PlayStation、Xbox 及 Meta Quest VR 全终端，依托遍布全球的边缘数据中心实现毫秒级万人同服物理仿真。\n              </p>\n            </div>\n\n            <!-- 壁垒 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">强社交关系链与用户年龄层上移</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                伴随 Z 世代与 Alpha 世代共同成长，Roblox <strong>13 岁以上用户占比已突破 60%</strong>，其中 <strong>18+ 成人用户</strong>成为增速最快群体。虚拟形象、实时语音派对与好友列表沉淀了极强的社交网络效应，大幅延长用户生命周期（LTV）与付费意愿。\n              </p>\n            </div>\n\n            <!-- 壁垒 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">AI 赋能创作者工具矩阵（Cube 3D）</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                推出自研 <strong>Cube 3D 基础生成式大模型</strong>（支持文本/图像一键生成带物理碰撞属性的完整 3D 网格与场景）、<strong>Code Assistant</strong> 自动编写 Luau 脚本以及<strong>实时多语言文本/语音同声翻译</strong>，让全球亿万玩家无障碍跨国社交并推动创作“平权化”。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河量化雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">互动娱乐平台五维护城河量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Roblox vs 传统 3A 游戏大厂 vs 社交与元宇宙平台（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比 (Competitive Landscape)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-rblx-600 dark:text-rblx-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：UGC 生态垄断与跨界注意力争夺</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-rblx-500 text-white shadow-sm transition\">全部阵营</button>\n            <button onclick=\"filterCompetitors('gaming')\" data-filter=\"gaming\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">传统沙盒与3A大厂</button>\n            <button onclick=\"filterCompetitors('social')\" data-filter=\"social\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">社交与元宇宙生态</button>\n            <button onclick=\"filterCompetitors('aicreator')\" data-filter=\"aicreator\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">AI 创作者平台</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[180px]\">竞争平台与所属巨头</th>\n                  <th class=\"py-4 px-4 min-w-[125px]\">活跃用户量级</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">内容供给模式</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">开发者分润机制</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">变现与合规壁垒</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞合关系评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：Roblox 行业基准 -->\n                <tr data-category=\"core\" class=\"bg-rblx-500/5 dark:bg-rblx-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-rblx-500 text-white text-[10px] font-bold\">行业基准</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">Roblox (RBLX)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全端 UGC 社交 + Cube 3D AI</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~1.44亿 DAU</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">100% 纯 UGC 双边生态</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-900 dark:text-white font-semibold\">DevEx 年分润 &gt;$1.2B</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Robux + 广告 · 严苛儿童安全审核</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>绝对霸主：</strong>移动端覆盖率与低门槛创作工具全球无出其右，社交网络黏性与跨端分发能力构筑深厚护城河。\n                  </td>\n                </tr>\n\n                <!-- 行 2：Epic Games (Fortnite / UEFN) -->\n                <tr data-category=\"aicreator\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Fortnite / UEFN</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Epic Games (私营/腾讯参股)</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~7000万+ MAU</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-accent-500/15 text-accent-700 dark:text-accent-400\">PGC 第一方大作 + UEFN</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-accent-600 dark:text-accent-400 font-semibold\">40% 净收入按参与度分配</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">PC/主机强变现 · 移动端受阻</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>最强直接竞争者：</strong>UEFN 虚幻引擎画质上限极高且分成比例优厚，但开发门槛显著高于 Roblox，且在 iOS/Android 移动生态受限。\n                  </td>\n                </tr>\n\n                <!-- 行 3：微软 Minecraft -->\n                <tr data-category=\"gaming\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Minecraft (我的世界)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Microsoft (NASDAQ: MSFT)</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~1.7亿+ MAU</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">买断制沙盒 + 模组市场</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Marketplace 创作者分成</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">买断+订阅 Realms 稳健</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>经典常青沙盒：</strong>IP 影响力深厚，但底层架构偏单机/小服建造，缺乏 Roblox 式的实时社交大厅、跨体验虚拟经济与多样化玩法引擎。\n                  </td>\n                </tr>\n\n                <!-- 行 4：Take-Two / EA 传统 3A 游戏大厂 -->\n                <tr data-category=\"gaming\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Take-Two (GTA VI) / EA</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">传统 3A 游戏发行巨头 (TTWO/EA)</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">依赖单款大作周期</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">重资产 PGC 专业工作室</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-500 dark:text-slate-400\">封闭研发 (FiveM 有限模组)</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">$70 买断 + 在线内购</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>重研发周期模式：</strong>单品毛利高，但研发费用率高、上线空窗期业绩波动大；GTA Online 收购 FiveM 后正试图借鉴 UGC 模组经济。\n                  </td>\n                </tr>\n\n                <!-- 行 5：Meta Horizon Worlds & Discord -->\n                <tr data-category=\"social\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Meta Horizon / Discord</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">VR 元宇宙与游戏语音社交</div>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">Discord ~2亿+ MAU</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-500/15 text-indigo-700 dark:text-indigo-400\">社群频道 / VR 社交空间</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Discord 嵌入式应用分成</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Nitro 订阅 / VR 硬件依赖</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>相邻赛道竞合：</strong>Horizon 仍受限于 VR 头显普及度；Discord 虽聚集大量游戏玩家，但缺乏内置 3D 物理引擎与成熟虚拟商品经济闭环。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- 互动图表 3：主流游戏与 UGC 平台商业模式对比图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">主流游戏与 UGC 平台商业效率对比（自由现金流率 vs 内容研发负担）</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">Roblox 凭借 UGC 众包模式实现零前置内容沉没成本，自由现金流转化率（FCF / Bookings）已跻身行业第一梯队</p>\n            </div>\n            <span class=\"text-xs font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded\">轻资产平台规模效应持续放大</span>\n          </div>\n          <div class=\"relative h-60 w-full\">\n            <canvas id=\"compEfficiencyChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值体系 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：穿透递延会计，锚定 EV / Bookings 与 FCF</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">机构估值核心：EV / Bookings · EV / Adj. EBITDA · DCF</span>\n        </div>\n\n        <!-- 1. 财务健康度剖析三支柱卡片 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-wider\">Negative Working Capital</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">极强经营现金流与 FCF 转化率</h3>\n            <div class=\"mt-2.5 text-2xl font-extrabold font-mono text-slate-900 dark:text-white\">$1.36B FCF (20.1% 率)</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              先收款（Robux 预售）后摊销（~28 个月递延确认）的商业模式赋予公司天然的负营运资本优势。随着资本开支（CapEx）占 Bookings 比例从早期基建高峰回落至个位数，经营现金流高度转化为自由现金流。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase tracking-wider\">Fortress Balance Sheet</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">高现金储备与低息债务结构</h3>\n            <div class=\"mt-2.5 text-2xl font-extrabold font-mono text-slate-900 dark:text-white\">净现金储备 ~$3.8B+</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              账面现金、等价物及短期投资充裕，长期债务主要为低票面利率优先票据（2030 年到期），无短期偿债压力，为自研 AI 算力推理集群投入与潜在股票回购提供坚实安全垫。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-rblx-600 dark:text-rblx-400 uppercase tracking-wider\">SBC Control & Operating Leverage</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">股权激励（SBC）收敛与盈利拐点</h3>\n            <div class=\"mt-2.5 text-2xl font-extrabold font-mono text-slate-900 dark:text-white\">SBC / Bookings 持续下行</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              过去市场诟病的 GAAP 账面亏损主要源于两大非现金/会计因素：① 递延收入摊销滞后于 Bookings 增长；② 工程师团队高额股权激励（SBC）。随研发人员招聘放缓与收入体量跃升，SBC 占 Bookings 比重持续收敛，推动 Adjusted EBITDA 利润率迈向 22%–25%+。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 机构估值体系重塑说明 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">机构主流估值体系解析：为何剔除 GAAP P/E，锚定 EV / Bookings 与 FCF？</h3>\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-5\">由于递延收入会计准则在高速增长期人为压低了 GAAP 净利润，华尔街机构采用以下三大核心估值锚进行定价：</p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n            <div class=\"p-4 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200 dark:border-slate-700\">\n              <div class=\"flex items-center justify-between mb-1.5\">\n                <span class=\"text-xs font-bold text-rblx-600 dark:text-rblx-400\">估值锚 01 · 规模增长基准</span>\n                <span class=\"font-mono text-xs font-bold px-2 py-0.5 rounded bg-rblx-500/15 text-rblx-600 dark:text-rblx-400\">EV / Bookings</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">企业价值 / 年度预订额倍数</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-1.5 leading-relaxed\">\n                直接反映当期真实用户消费流水规模，消除 28 个月会计递延带来的时间错配，历史波动区间在 5x–9x，当前处于成长型平台合理中枢。\n              </p>\n            </div>\n\n            <div class=\"p-4 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200 dark:border-slate-700\">\n              <div class=\"flex items-center justify-between mb-1.5\">\n                <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400\">估值锚 02 · 真实经营盈利</span>\n                <span class=\"font-mono text-xs font-bold px-2 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400\">EV / Adj. EBITDA</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">加回递延收入净变动的息税折旧前利润</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-1.5 leading-relaxed\">\n                在 GAAP EBITDA 基础上加回“当期递延收入净增加额”与非现金 SBC，精准还原平台当期真实的经济盈利造血能力与经营杠杆弹性。\n              </p>\n            </div>\n\n            <div class=\"p-4 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200 dark:border-slate-700\">\n              <div class=\"flex items-center justify-between mb-1.5\">\n                <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400\">估值锚 03 · 终局现金流折现</span>\n                <span class=\"font-mono text-xs font-bold px-2 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">DCF & EV / FCF</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">远期 25%+ FCF 利润率折现模型</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-1.5 leading-relaxed\">\n                伴随网页直充比例上升（毛利率改善）与广告高毛利增量注入，管理层长期目标指向 25%+ 自由现金流率，支撑中长期 DCF 估值上行空间。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 交互图表 4：2021–2026E 自由现金流率与 SBC 占 Bookings 比例收敛趋势双轴图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 自由现金流率（FCF % Bookings）与股权激励（SBC % Bookings）收敛剪刀差</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">运营杠杆释放的直观印证：FCF 利润率由低谷强力回升至 20%+，同时 SBC 占比持续下降</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded\">盈利与现金流质量显著改善</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"fcfSbcChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策、情景推演与风险配置 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-rblx-600 dark:text-rblx-400\">Section 05 · Investment Decision, Scenario Modeling & Risk</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策、三情景推演与风险配置框架</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置定位：平台型高弹性成长仓位 · 紧盯现金流率与直充进度</span>\n        </div>\n\n        <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 乐观牛市 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">乐观牛市 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：30%</span>\n              </div>\n              <div class=\"text-lg font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标：8.5x – 9.5x EV/Bookings</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>18+ 成人化与 Cube 3D AI 驱动 DAU 突破 2 亿，品牌视频/3D 广告年化破 $10 亿，网页/PC 直充比例突破 45%，推动长期 FCF 利润率超 <strong>25%</strong>，实现高速增长与估值倍数的戴维斯双击。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n              情景特征：平台网络效应全面货币化，向 10 亿日活愿景加速迈进\n            </div>\n          </div>\n\n          <!-- 基准情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n              </div>\n              <div class=\"text-lg font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标：6.5x – 7.5x EV/Bookings</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>DAU 与 Bookings 维持 18%–22% 稳健双位数复合增长，亚太与新兴市场用户放量与欧美 ABPDAU 稳步提升形成互补，SBC 占 Bookings 比例持续收敛，FCF 利润率稳定在 <strong>20%–23%</strong> 区间。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n              情景特征：现金流复利稳步兑现，驱动市值随 Bookings 同步扩张\n            </div>\n          </div>\n\n          <!-- 悲观熊市 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">悲观熊市 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n              </div>\n              <div class=\"text-lg font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守：4.0x – 4.5x EV/Bookings</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>欧美青少年安全合规监管趋严限制低龄用户消费权限，或短视频（TikTok/YouTube Shorts）与 Fortnite UEFN 分流用户时长导致 Bookings 增速放缓至个位数，同时 AI 推理算力成本吞噬毛利改善空间。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n              情景特征：账面净现金储备与正向 FCF 提供底部估值托底\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险矩阵与机构应对缓释机制</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 风险 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 青少年安全合规与年龄验证监管</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球未成年人保护法规趋严与消费限制</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                欧美及多国监管机构对未成年人社交隐私、实名年龄认证及游戏内购消费上限持续收紧，若强制实施更严苛的家长同意门槛，可能短期影响部分低龄用户活跃度与付费转化。\n              </p>\n            </div>\n\n            <!-- 风险 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 平台抽成与移动应用商店渠道依赖</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Apple App Store 与 Google Play 30% 渠道税</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                移动端仍占据 Roblox 超过七成的 DAU 流量，移动应用商店高达 30% 的支付抽成直接压缩平台毛利率；虽欧美反垄断法案（如 EU DMA）打开外链支付口子，但用户支付习惯迁移仍需周期。\n              </p>\n            </div>\n\n            <!-- 风险 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · AI 算力与云端基建资本开支压力</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">3D 生成式 AI 模型训练与实时安全审核推理成本</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                支持千万级并发场景的 Cube 3D 模型生成、AI 实时多语种语音翻译及全天候 AI 内容安全审核，对 GPU 推理集群提出高要求，若算力成本控制不当可能延缓毛利率扩张。\n              </p>\n            </div>\n\n            <!-- 风险 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 区域扩张带来的结构性 ABPDAU 稀释</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">新兴市场 DAU 高增拉低全局人均预订额</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                亚太及拉美（如印度、东南亚、巴西）是当前 DAU 增长最快的引擎，但其人均付费能力远低于北美及西欧，可能导致合并报表层面的整体 ABPDAU 出现结构性摊薄，需依赖沉浸式品牌广告补齐变现。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 季度基本面跟踪 KPI 交互核查清单 (Checklist) -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">机构季度基本面跟踪 KPI 交互核查清单（Checklist）</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">点击勾选机构季报已验证达标的六大核心运营与财务指标（状态自动本地保存至 localStorage）</p>\n            </div>\n            <div class=\"flex items-center space-x-2 no-print\">\n              <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-rblx-500/15 text-rblx-600 dark:text-rblx-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n              <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n            </div>\n          </div>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5 mt-4\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rblx-kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EE3124] focus:ring-rblx-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Bookings（预订额）季度同比增速</span>\n                  <span class=\"text-[11px] font-mono text-rblx-600 dark:text-rblx-400 font-semibold shrink-0\">核心规模锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  剔除递延收入会计滞后影响，跟踪全球 Bookings 是否稳健维持在 18%–25%+ 高景气增长通道。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rblx-kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EE3124] focus:ring-rblx-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 13+ 岁及 18+ 成人用户占 DAU 比例</span>\n                  <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">成人化破圈指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪 13 岁以上核心用户占比（&gt;60%）及 18+ 成人人群增速，验证高购买力群体扩张与品牌广告主吸引力。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rblx-kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EE3124] focus:ring-rblx-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 分区域 ABPDAU（日均单用户预订额）变动</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">区域变现质量</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  分拆观察北美（US & Canada）与西欧高价值区 ABPDAU 是否保持同比正增长，不被亚太扩张所掩盖。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rblx-kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EE3124] focus:ring-rblx-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. DevEx 开发者分润占 Bookings 比例</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">生态健康度指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪 DevEx 占 Bookings 比例（稳态 ~18%–21%）及年收入超百万美元工作室数量，确保创作者生态持续繁荣。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rblx-kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EE3124] focus:ring-rblx-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. PC / 网页端直充及礼品卡支付占比提升</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">毛利率催化剂</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测绕开 Apple/Google 30% 渠道税的网页直充与桌面端支付占比提升幅度，直接驱动 COGS 费用率下行。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rblx-kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EE3124] focus:ring-rblx-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 自由现金流率（FCF / Bookings）向 25% 迈进</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">现金流终局锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  验证在保持 AI 算力投入的同时，季度滚动 FCF 利润率能否稳步守住 20% 以上并向 25% 长期目标攀升。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>Roblox (NYSE: RBLX) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：FY2025 财报及 2026 年 11 月市场一致预期 (FY26E)</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开财报、互动娱乐与 UGC 行业调研数据及机构估值模型整理生成，旨在提供结构化的商业模式与投资逻辑参考。文中涉及的 2026E 预订额与现金流预测、区域 ABPDAU 结构估算及三情景估值推演均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步重绘所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与侧边导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-rblx-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-rblx-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-rblx-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-rblx-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'rblx_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 6. Chart.js 四大交互数据图表与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compEffChartInstance = null;\n    let fcfSbcChartInstance = null;\n    let currentBizMode = 'financial';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 视图 A：2021–2026E Bookings、GAAP Revenue 与 FCF 跃升趋势\n      const finConfig = {\n        type: 'bar',\n        data: {\n          labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '全年预订额 Bookings ($B)',\n              data: [2.73, 2.87, 3.52, 4.37, 6.78, 8.25],\n              backgroundColor: '#EE3124',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'bar',\n              label: 'GAAP 营业收入 ($B)',\n              data: [1.92, 2.23, 2.80, 3.60, 4.89, 6.35],\n              backgroundColor: '#3B82F6',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '自由现金流 FCF ($B)',\n              data: [0.56, -0.06, 0.12, 0.64, 1.36, 1.85],\n              borderColor: '#10B981',\n              backgroundColor: '#10B981',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 9.5,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: -0.5,\n              max: 2.5,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      // 视图 B：全球五大区域 DAU 规模 vs 日均单用户预订额 (ABPDAU)\n      const regConfig = {\n        type: 'bar',\n        data: {\n          labels: ['北美 (US & Canada)', '欧洲 (Europe)', '亚太 (APAC)', '拉美 (LATAM)', '世界其他 (RoW)'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '区域日活跃用户 DAU (百万)',\n              data: [26.5, 31.0, 44.5, 22.0, 20.0],\n              backgroundColor: ['#3B82F6', '#06B6D4', '#EE3124', '#6366F1', '#64748B'],\n              borderRadius: 6,\n              barThickness: 34,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '日均单用户预订额 ABPDAU ($)',\n              data: [0.36, 0.14, 0.06, 0.05, 0.04],\n              borderColor: '#10B981',\n              backgroundColor: '#10B981',\n              borderWidth: 2.8,\n              pointRadius: 5,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `区域 DAU: ${ctx.parsed.y} 百万`\n                  : `日均单用户预订额 ABPDAU: $${ctx.parsed.y.toFixed(2)}`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 55,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + 'M' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              max: 0.45,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(2) }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'financial' ? finConfig : regConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnFin = document.getElementById('btn-chart-fin');\n      const btnReg = document.getElementById('btn-chart-reg');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'financial') {\n        btnFin.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-rblx-600 dark:text-rblx-400 shadow-sm transition';\n        btnReg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = '2021–2026E 预订额 (Bookings)、GAAP 营收与自由现金流跃升';\n        subEl.textContent = '2025 Bookings 达 $6.78B (+55%)，预先现金流沉淀推动 FCF 飙升至 $1.36B';\n      } else {\n        btnReg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-rblx-600 dark:text-rblx-400 shadow-sm transition';\n        btnFin.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = '全球五大区域 DAU 分布与日均单用户预订额 (ABPDAU) 结构';\n        subEl.textContent = '北美以高 ABPDAU ($0.36/天) 贡献核心利润，亚太 (44.5M DAU) 驱动全球用户渗透';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            'UGC 内容供给与创作者生态',\n            '社交关系链与用户黏性',\n            'AI 生成工具与创作平权',\n            '全平台跨端引擎分发',\n            '未成年人安全与信任合规'\n          ],\n          datasets: [\n            {\n              label: 'Roblox (RBLX)',\n              data: [9.8, 9.5, 9.3, 9.6, 9.4],\n              borderColor: '#EE3124',\n              backgroundColor: 'rgba(238, 49, 36, 0.22)',\n              pointBackgroundColor: '#EE3124',\n              borderWidth: 2.5\n            },\n            {\n              label: '社交与元宇宙平台 (Fortnite/Horizon)',\n              data: [7.6, 8.4, 7.8, 7.2, 7.5],\n              borderColor: '#3B82F6',\n              backgroundColor: 'rgba(59, 130, 246, 0.14)',\n              pointBackgroundColor: '#3B82F6',\n              borderWidth: 1.8\n            },\n            {\n              label: '传统 3A 游戏发行大厂',\n              data: [4.2, 6.5, 6.0, 6.8, 7.0],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.12)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initCompEffChart() {\n      const ctx = document.getElementById('compEfficiencyChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (compEffChartInstance) compEffChartInstance.destroy();\n      compEffChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            'Roblox (纯 UGC 平台 · 零前置游戏研发)',\n            'Electronic Arts (EA · 体育年货+在线服务)',\n            'Take-Two (TTWO · 重型 3A 大作长周期)',\n            'Ubisoft / 传统二线 3A 发行商平均'\n          ],\n          datasets: [\n            {\n              label: '自由现金流利润率 FCF Margin (%)',\n              data: [20.1, 21.5, 11.2, 4.5],\n              backgroundColor: '#10B981',\n              borderRadius: 5,\n              barThickness: 18\n            },\n            {\n              label: '内容/引擎研发费用率 R&D (% 流水)',\n              data: [19.5, 31.0, 38.5, 42.0],\n              backgroundColor: '#64748B',\n              borderRadius: 5,\n              barThickness: 18\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 50,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initFcfSbcChart() {\n      const ctx = document.getElementById('fcfSbcChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (fcfSbcChartInstance) fcfSbcChartInstance.destroy();\n      fcfSbcChartInstance = new Chart(ctx, {\n        type: 'line',\n        data: {\n          labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n          datasets: [\n            {\n              label: '自由现金流率 (FCF % Bookings)',\n              data: [20.5, -2.1, 3.4, 14.6, 20.1, 22.4],\n              borderColor: '#10B981',\n              backgroundColor: 'rgba(16, 185, 129, 0.16)',\n              fill: true,\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.3\n            },\n            {\n              label: '股权激励费用率 (SBC % Bookings)',\n              data: [12.5, 20.5, 24.7, 22.8, 17.5, 14.8],\n              borderColor: '#EE3124',\n              backgroundColor: 'rgba(238, 49, 36, 0.08)',\n              borderDash: [5, 4],\n              borderWidth: 2.5,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.3\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.y}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              min: -5,\n              max: 30,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initCompEffChart();\n      initFcfSbcChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      initBizChart();\n      initRadarChart();\n      initCompEffChart();\n      initFcfSbcChart();\n    });\n  </script>\n</body>\n</html>"};
